import functools

def log(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        print(f"calling {fn.__name__}")
        return fn(*args, **kwargs)
    return wrapper

def cache(fn):
    memo = {}
    def wrapped(*args):
        if args not in memo:
            memo[args] = fn(*args)
        return memo[args]
    return wrapped

@staticmethod
def size():
    return 10

@classmethod
def make(cls):
    return cls()

@property
def name(self):
    return self._name

def read_file(path):
    with open(path, 'r') as f:
        return f.read()

def copy_file(src, dst):
    with open(src, 'rb') as fin, open(dst, 'wb') as fout:
        fout.write(fin.read())

def log(*args, **kwargs):
    print(args)
    print(kwargs)

def divide(a, b):
    if b == 0:
        raise ValueError("divide by zero")
    return a / b

def try_parse(s):
    try:
        return int(s)
    except ValueError as e:
        print(f"bad: {e}")
        return None

def safe_open(path):
    try:
        return open(path)
    except FileNotFoundError:
        return None
    finally:
        print("attempted open")

def count_up(n):
    for i in range(n):
        yield i

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def distance(self):
        return (self.x ** 2 + self.y ** 2) ** 0.5

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return f"{self.name} makes a sound"

class Dog(Animal):
    def speak(self):
        return f"{self.name} barks"

def build_url(base, **params):
    parts = [f"{k}={v}" for k, v in params.items()]
    return base + "?" + "&".join(parts)

def min_max(xs):
    lo, hi = min(xs), max(xs)
    return lo, hi

def head_tail(xs):
    head, *tail = xs
    return head, tail

def read_lines(path):
    lines = []
    with open(path) as f:
        while (line := f.readline()):
            lines.append(line.strip())
    return lines
